23	std::atomic_size_t ScalableAllocator::global_allocator_id_(0U);
24	
25	ScalableAllocator::ScalableAllocator(SpanAllocator &span_allocator, const ScalableConfig &cfg)
26	    : allocator_id_(++global_allocator_id_),
27	      allocator_id_with_type_("[allocator_" + std::to_string(allocator_id_) + "]"),
28	      config_{cfg},
29	      page_mem_size_{PageLen_GetMemSize(1, cfg.page_idem_num)},
30	      span_layer_capacity_{1 + SpanLayerId_GetIdFromSize(cfg.page_mem_size_total_threshold, cfg.page_idem_num)},
31	      uncacheable_layer_start_{SpanLayerId_GetIdFromSize(cfg.uncacheable_size_threshold, cfg.page_idem_num)},
32	      span_layer_page_capacity_{PageLen_GetLenFromSize(cfg.page_mem_size_total_threshold, cfg.page_idem_num)},
33	      span_allocator_{span_allocator},
34	      layer_allocator_{cfg.span_layer_prepared_count} {
35	  span_layers_.resize(span_layer_capacity_);
36	  // 不加nothrow，理由：由于构造函数无法返回失败，且这是关键资源申请，如果申请失败允许进程退出。
37	  auto layer_lut = static_cast<SpanLayerLut *>(new SpanLayerQuickLut{span_layers_});
38	  if (layer_lut != nullptr) {
39	    span_layer_lut_.reset(layer_lut);
40	  }
41	}
42	
43	ScalableAllocator::~ScalableAllocator() {
44	  try {
45	    (void)Finalize();
46	    span_layers_.clear();
47	  } catch (const std::exception &) {
48	    // do nothing
49	  }
50	}
51	
52	ge::Status ScalableAllocator::Finalize() {
53	  if (!span_layers_.empty() && span_layer_lut_ != nullptr && occupied_spans_.empty()) {
54	    span_layer_lut_->Release(span_allocator_);
55	    for (auto layer : span_layers_) {
56	      if (layer != nullptr) {
57	        if (layer->GetLayerId() < span_layers_.size()) {
58	          span_layers_[layer->GetLayerId()] = nullptr;
59	        }
60	        layer_allocator_.Free(*layer);
61	      }
62	    }
63	  }
64	  return ge::SUCCESS;
65	}
66	
67	MemSize ScalableAllocator::GetAllocSize(const MemSize size) const {
68	  return (size < page_mem_size_) ? page_mem_size_ : MemSize_GetAlignedOf(size, page_mem_size_);
69	}
70	
71	PageLen ScalableAllocator::GetlayerSpanCapacity(const SpanLayerId layer_id) const {
72	  if ((layer_id >= uncacheable_layer_start_) || (layer_id == 0U)) {
73	    return 0U;
74	  }
75	  return std::min(span_layer_page_capacity_ / layer_id, static_cast<uint32_t>(config_.span_count_in_layer_threshold));
76	}
77	
78	PageSpan *ScalableAllocator::FetchLayerSpan(const SpanLayerId layer_id) {
79	  if (span_layers_.empty() || (span_layers_[layer_id] == nullptr)) {
80	    return nullptr;
81	  }
82	
83	  auto span = PopSpanFromLayer(*span_layers_[layer_id]);
84	  if (span != nullptr) {
85	    OccupySpan(*span, layer_id);
86	  }
87	  return span;
88	}
89	
90	PageSpan *ScalableAllocator::BlockAlloc(ge::Allocator &allocator, const BlockAddr block_addr, const MemAddr addr,
91	                                        const size_t size) {
92	  auto *mem = span_allocator_.Alloc();
93	  if (mem == nullptr) {
94	    return nullptr;
95	  }
96	  auto span = new (mem) PageSpan{allocator, *this, block_addr, addr, size};
97	  return span;
98	}
99	
100	SpanLayer *ScalableAllocator::FetchSpanLayer(const SpanLayerId layer_id) {
101	  if (span_layers_.empty() || (layer_id >= span_layer_capacity_)) {
102	    return nullptr;
103	  }
104	
105	  if (span_layers_[layer_id] != nullptr) {
106	    return span_layers_[layer_id];
107	  }
108	
109	  auto *mem = layer_allocator_.Alloc();
110	  if (mem == nullptr) {
111	    return nullptr;
112	  }
113	  auto newLayer = new (mem) SpanLayer(layer_id, GetlayerSpanCapacity(layer_id));
114	  span_layers_[layer_id] = newLayer;
115	  span_layer_lut_->OnLayerCreated(*newLayer);
116	  return newLayer;
117	}
118	
119	PageSpan *ScalableAllocator::FetchSplitedSpan(ge::Allocator &allocator, const SpanLayerId fix_layer_id,
120	                                              const SpanLayerId fit_layer_id, const MemSize size) {
121	  if (span_layers_.empty() || (fit_layer_id <= fix_layer_id)) {
122	    return nullptr;
123	  }
124	  if (span_layers_[fit_layer_id] == nullptr) {
125	    return nullptr;
126	  }
127	
128	  auto span = PopSpanFromLayer(*span_layers_[fit_layer_id]);
129	  if (span == nullptr) {
130	    return nullptr;
131	  }
132	  return SplitSpan(allocator, fix_layer_id, fit_layer_id, span, size);
133	}
134	
135	PageSpan *ScalableAllocator::SplitSpan(ge::Allocator &allocator, const SpanLayerId fix_layer_id,
136	                                       const SpanLayerId fit_layer_id, PageSpan *const span, const MemSize size) {
137	  LLM_ASSERT_NOTNULL(span);
138	  PageLen left_page_len = fit_layer_id - fix_layer_id;
139	  const auto buddy_addr =
140	      PageLen_ForwardAddr(left_page_len, config_.page_idem_num, reinterpret_cast<MemAddr>(span->GetAddr()));
141	  const auto buddy_span = BlockAlloc(allocator, nullptr, buddy_addr, static_cast<size_t>(size));
142	  if (buddy_span == nullptr) {
143	    return nullptr;
144	  }
145	
146	  span->SetBuddy(*buddy_span);
147	  span->SetPageLen(left_page_len);
148	
149	  const auto layer = FetchSpanLayer(left_page_len);
150	  if (layer == nullptr) {
151	    span_allocator_.Free(*span);
152	    return nullptr;
153	  }
154	  PushSpanToLayer(*layer, *span);
155	  OccupySpan(*buddy_span, fix_layer_id);
156	  return buddy_span;
157	}
158	
159	PageSpan *ScalableAllocator::AllocImp(ge::Allocator &allocator, const MemSize size) {
160	  MemSize alloc_size = GetAllocSize(size);
161	  SpanLayerId fix_layer_id = SpanLayerId_GetIdFromSize(alloc_size, config_.page_idem_num);
162	  if ((fix_layer_id >= span_layer_capacity_) || (span_layer_lut_ == nullptr)) {
163	    return nullptr;
164	  }
165	  auto span = FetchLayerSpan(fix_layer_id);
166	  SpanLayerId fit_layer_id = 0U;
167	  if (span == nullptr) {
168	    fit_layer_id = span_layer_lut_->FindFitLayerId(fix_layer_id + 1, config_.span_layer_lift_max);
169	    if (fit_layer_id >= span_layer_capacity_) {
170	      span = nullptr;
171	    } else {
172	      span = FetchSplitedSpan(allocator, fix_layer_id, fit_layer_id, alloc_size);
173	    }
174	  }
175	
176	  if (span != nullptr) {
177	    LOG_BY_TYPE(DLOG_INFO, "size:%zu block_size:%zu", size, span->GetSize());
178	    span->SetRealSize(size);
179	  }
180	  return span;
181	}
182	
183	PageSpan *ScalableAllocator::Alloc(ge::Allocator &allocator, const MemSize size) {
184	  if (size > config_.page_mem_size_total_threshold) {
185	    LLMLOGE(ge::FAILED, "%s [ScalableAllocator]: size:%lu > mem_size_total_threshold:%lu", GetId().c_str(), size,
186	            config_.page_mem_size_total_threshold);
187	    return nullptr;
188	  }
189	
190	  PageSpan *span = nullptr;
191	  span = AllocImp(allocator, size);
192	  if (span != nullptr) {
193	    theory_size_ += span->GetSize();
194	    real_theory_size_ += span->GetRealSize();
195	    if (real_theory_size_ > real_theory_min_size_) {
196	      real_theory_min_size_ = real_theory_size_;
197	    }
198	
199	    if (theory_size_ > theory_min_size_) {
200	      theory_min_size_ = theory_size_;
201	    }
202	    LOG_BY_TYPE(DLOG_INFO, "Malloc block size:%llu allocate_size:%zu mem_addr:%p. span addr %p", size, span->GetSize(),
203	                span->GetAddr(), span);
204	  }
205	  return span;
206	}
207	
208	PageSpan *ScalableAllocator::PickOutBuddy(PageSpan *const buddy_span) {
209	  if (span_layers_.empty() || (buddy_span == nullptr)) {
210	    return nullptr;
211	  }
212	  if (buddy_span->GetCount() != 0U) {
213	    return nullptr;
214	  }
215	
216	  PageLen page_len = buddy_span->GetPageLen();
217	  if (page_len >= span_layer_capacity_ || span_layers_[page_len] == nullptr) {
218	    return nullptr;
219	  }
220	  RemoveFromLayer(*span_layers_[page_len], *buddy_span);
221	  return buddy_span;
222	}
223	
224	PageSpan *ScalableAllocator::TryMergePrev(PageSpan &span) {
225	  auto prev_buddy = PickOutBuddy(span.GetPrevBuddy());
226	  if (prev_buddy == nullptr) {
227	    return &span;
228	  }
229	
230	  prev_buddy->MergeBuddy(span);
231	  span_allocator_.Free(span);
232	  return prev_buddy;
233	}
234	
235	PageSpan *ScalableAllocator::TryMergeNext(PageSpan &span) {
236	  auto next_buddy = PickOutBuddy(span.GetNextBuddy());
237	  if (next_buddy == nullptr) {
238	    return &span;
239	  }
240	
241	  span.MergeBuddy(*next_buddy);
242	  span_allocator_.Free(*next_buddy);
243	  return &span;
244	}
245	
246	void ScalableAllocator::Free(ge::MemBlock *block) {
247	  auto span = reinterpret_cast<PageSpan *>(block);
248	  if ((span == nullptr) || (span_layer_lut_ == nullptr)) {
249	    return;
250	  }
251	
252	  if (theory_size_ >= span->GetRealSize()) {
253	    real_theory_size_ -= span->GetRealSize();
254	    theory_size_ -= span->GetSize();
255	  }
256	  LOG_BY_TYPE(DLOG_INFO, "Free block theory_size_:%zu theory_min_size_:%zu allock_size:%zu mem_addr:%p.", theory_size_,
257	              theory_min_size_, span->GetSize(), span->GetAddr());
258	
259	  occupied_spans_.remove(*span);
260	  span = TryMergeNext(*span);
261	  span = TryMergePrev(*span);
262	  FreeSpan(*span);
263	}
264	
265	PageSpan *ScalableAllocator::PopSpanFromLayer(SpanLayer &layer) {
266	  PageSpan *span = layer.PopSpan();
267	  span_layer_lut_->OnLayerRemoveSpan(layer);
268	  return span;
269	}
270	
271	void ScalableAllocator::PushSpanToLayer(SpanLayer &layer, PageSpan &span) {
272	  layer.PushSpan(span);
273	  span_layer_lut_->OnLayerAddSpan(layer);
274	}
275	
276	void ScalableAllocator::RemoveFromLayer(SpanLayer &layer, PageSpan &span) {
277	  layer.Remove(span);
278	  span_layer_lut_->OnLayerRemoveSpan(layer);
279	}
280	
281	void ScalableAllocator::OccupySpan(PageSpan &span, PageLen page_len) {
282	  span.Alloc(page_len);
283	  occupied_spans_.push_front(span);
284	  alloc_succ_count_++;
285	}
286	
287	void ScalableAllocator::FreeSpan(PageSpan &span) {
288	  SpanLayer *layer = nullptr;
289	  layer = FetchSpanLayer(span.GetPageLen());
290	  if (layer != nullptr) {
291	    PushSpanToLayer(*layer, span);
292	    free_succ_count_++;
293	  }
294	}
295	
296	void ScalableAllocator::PrintDetails(const int32_t level) const {
297	  if (((level != DLOG_EVENT) && (!LlmIsLogEnable(LLM_MODULE_NAME, level)))) {
298	    return;
299	  }
300	
301	  LOG_BY_TYPE(level, "Allocator memory: [alloc count:%zu free count:%zu]", alloc_succ_count_, free_succ_count_);
302	
303	  std::map<size_t, size_t> occupied_span_stat;
304	  size_t total_page_count = 0U;
305	  for (const auto &span : occupied_spans_) {
306	    total_page_count += span.GetPageLen();
307	    occupied_span_stat[span.GetPageLen()]++;
308	  }
309	
310	  LOG_BY_TYPE(level, "Using: [span count:%zu page count:%zu total size:%llu]", occupied_spans_.size(), total_page_count,
311	              PageLen_GetMemSize(total_page_count, config_.page_idem_num));
312	  for (const auto &stat : occupied_span_stat) {
313	    LOG_BY_TYPE(level, "    |-span: [size:%-11llu count:%-5zu]", PageLen_GetMemSize(stat.first, config_.page_idem_num),
314	                stat.second);
315	  }
316	
317	  size_t total_span_count = 0U;
318	  MemSize total_mem_size = 0U;
319	  total_page_count = 0U;
320	  LOG_BY_TYPE(level, "Freed span layers: [level:%u, count:%zu]", span_layer_capacity_, span_layer_lut_->size());
321	  for (const auto &layer_id : *span_layer_lut_) {
322	    if ((!span_layers_.empty()) && (layer_id < span_layer_capacity_) && (span_layers_[layer_id] != nullptr)) {
323	      total_span_count += span_layers_[layer_id]->GetSize();
324	      total_page_count += span_layers_[layer_id]->GetPageSize();
325	      total_mem_size += PageLen_GetMemSize(span_layers_[layer_id]->GetPageSize(), config_.page_idem_num);
326	    }
327	  }
328	
329	  LOG_BY_TYPE(level, "Freed: [span count:%zu page count:%zu total size:%llu]", total_span_count, total_page_count,
330	              total_mem_size);
331	  for (const auto &layer_id : *span_layer_lut_) {
332	    if ((!span_layers_.empty()) && (layer_id < span_layer_capacity_) && (span_layers_[layer_id] != nullptr)) {
333	      LOG_BY_TYPE(level, "    |-layer: [id:%-5u capacity:%-5zu size:%-11llu count:%-5zu]",
334	                  span_layers_[layer_id]->GetLayerId(), span_layers_[layer_id]->GetCapacity(),
335	                  PageLen_GetMemSize(span_layers_[layer_id]->GetLayerId(), config_.page_idem_num),
336	                  span_layers_[layer_id]->GetSize());
337	    }
338	  }
339	}
340	
341	const std::string &ScalableAllocator::GetId() const {
342	  return allocator_id_with_type_;
343	}
344	
345	ge::Status ScalableAllocator::InitFixSizedAllocator(ge::Allocator &allocator, void *base_addr, size_t size) {
346	  is_fix_sized_ = true;
347	  const auto span = BlockAlloc(allocator, nullptr, static_cast<uint8_t *>(base_addr), size);
348	  LLM_CHK_BOOL_RET_STATUS(span != nullptr, ge::FAILED, "Failed to alloc block.");
349	
350	  LLM_DISMISSABLE_GUARD(fail_guard, ([this, span]() { span_allocator_.Free(*span); }));
351	
352	  base_addr_ = span->GetAddr();
353	  LOG_BY_TYPE(DLOG_INFO, "base_addr:%p size:%zu", base_addr_, span->GetSize());
354	  // span is idle, so the usage count needs to be 0
355	  while (span->GetCount() > 0U) {
356	    span->SubCount();
357	  }
358	
359	  const SpanLayerId fit_layer_id = SpanLayerId_GetIdFromSize(size, ScalableAllocator::config_.page_idem_num);
360	  const auto layer = FetchSpanLayer(fit_layer_id);
361	  LLM_CHK_BOOL_RET_STATUS(layer != nullptr, ge::FAILED, "Failed to fetch span layer.");
362	  PushSpanToLayer(*layer, *span);
363	  PrintDetails(DLOG_EVENT);
364	  LLM_DISMISS_GUARD(fail_guard);
365	  return ge::SUCCESS;
366	}
367	}  // namespace llm
